export function buildTools(opts: { onSubagent?: (task: string) => Promise<string> }): Map<string, ToolSpec> {
  const tools = new Map<string, ToolSpec>();
  const add = (t: ToolSpec) => tools.set(t.name, t);

  add({
    name: "read_file",
    description: "Read a file. Returns numbered lines.",
    args: `{"path": string, "offset"?: number, "limit"?: number}`,
    needsApproval: false,
    subagentSafe: true,
    run: async (args) => {
      const path = resolvePath(str(args, "path"));
      if (!existsSync(path)) throw new Error(`file not found: ${path}`);
      const st = statSync(path);
      if (st.isDirectory()) throw new Error(`${path} is a directory — use ls`);
      if (st.size > 2_000_000) throw new Error(`file too large (${st.size} bytes)`);
      const lines = readFileSync(path, "utf8").split("\n");
      const offset = Number(args.offset ?? 1);
      const limit = Number(args.limit ?? 1500);
      const slice = lines.slice(offset - 1, offset - 1 + limit);
      const numbered = slice.map((l, i) => `${String(offset + i).padStart(5)}| ${l}`).join("\n");
      const more = lines.length > offset - 1 + limit ? `\n... [${lines.length} lines total]` : "";
      return cap(numbered + more);
    },
  });

  add({
    name: "write_file",
    description: "Create or overwrite a file with the given content. Parent dirs are created.",
    args: `{"path": string, "content": string}`,
    needsApproval: true,
    subagentSafe: false,
    run: async (args) => {
      const path = resolvePath(str(args, "path"));
      const content = typeof args.content === "string" ? args.content : "";
      mkdirSync(dirname(path), { recursive: true });
      const existed = existsSync(path);
      writeFileSync(path, content);
      return `${existed ? "overwrote" : "created"} ${path} (${content.length} chars)`;
    },
  });

  add({
    name: "edit_file",
    description:
      "Replace an exact string in a file. old_string must match exactly once (set all=true to replace every occurrence).",
    args: `{"path": string, "old_string": string, "new_string": string, "all"?: boolean}`,
    needsApproval: true,
    subagentSafe: false,
    run: async (args) => {
      const path = resolvePath(str(args, "path"));
      if (!existsSync(path)) throw new Error(`file not found: ${path}`);
      const oldStr = str(args, "old_string");
      const newStr = typeof args.new_string === "string" ? args.new_string : "";
      const content = readFileSync(path, "utf8");
      const count = content.split(oldStr).length - 1;
      if (count === 0) throw new Error(`old_string not found in ${path}`);
      if (count > 1 && !args.all)
        throw new Error(`old_string matches ${count} times — make it unique or pass "all": true`);
      const next = args.all ? content.split(oldStr).join(newStr) : content.replace(oldStr, newStr);
      writeFileSync(path, next);
      return `edited ${path} (${count} replacement${count > 1 ? "s" : ""})`;
    },
  });

  add({
    name: "ls",
    description: "List a directory with entry sizes.",
    args: `{"path"?: string}`,
    needsApproval: false,
    subagentSafe: true,
    run: async (args) => {
      const path = resolvePath(typeof args.path === "string" && args.path ? args.path : ".");
      const entries = readdirSync(path)
        .filter((e) => e !== "node_modules" && e !== ".git")
        .slice(0, 300)
        .map((e) => {
          try {
            const st = statSync(join(path, e));
            return st.isDirectory() ? `${e}/` : `${e} (${st.size}b)`;
          } catch {
            return e;
          }
        });
      return cap(entries.join("\n") || "(empty)");
    },
  });

  add({
    name: "glob",
    description: "Find files matching a glob pattern (e.g. **/*.ts), newest first.",
    args: `{"pattern": string, "path"?: string}`,
    needsApproval: false,
    subagentSafe: true,
    run: async (args) => {
      const root = resolvePath(typeof args.path === "string" && args.path ? args.path : ".");
      const glob = new Bun.Glob(str(args, "pattern"));
      const hits: Array<{ p: string; m: number }> = [];
      for await (const file of glob.scan({ cwd: root, dot: false })) {
        if (file.includes("node_modules/") || file.startsWith(".git/")) continue;
        try {
          hits.push({ p: file, m: statSync(join(root, file)).mtimeMs });
        } catch {
          hits.push({ p: file, m: 0 });
        }
        if (hits.length >= 500) break;
      }
      hits.sort((a, b) => b.m - a.m);
      return cap(hits.map((h) => h.p).join("\n") || "(no matches)");
    },
  });

  add({
    name: "grep",
    description: "Search file contents with a regex (ripgrep). Returns file:line:text matches.",
    args: `{"pattern": string, "path"?: string, "glob"?: string}`,
    needsApproval: false,
    subagentSafe: true,
    run: async (args) => {
      const pattern = str(args, "pattern");
      const path = resolvePath(typeof args.path === "string" && args.path ? args.path : ".");
      const globFlag = typeof args.glob === "string" && args.glob ? ["--glob", args.glob] : [];
      const hasRg = Bun.which("rg") !== null;
      const cmd = hasRg
        ? ["rg", "-n", "--max-count", "50", "--max-columns", "300", ...globFlag, "-e", pattern, path]
        : ["grep", "-rn", "-m", "50", "-E", pattern, path];
      const proc = Bun.spawn(cmd, { stdout: "pipe", stderr: "pipe" });
      const [out, code] = await Promise.all([new Response(proc.stdout).text(), proc.exited]);
      if (code > 1) throw new Error(`search failed (exit ${code})`);
      return cap(out.trim() || "(no matches)");
    },
  });

  add({
    name: "bash",
    description:
      "Run a shell command in the working directory. Output is captured. Use for builds, tests, git, installs.",
    args: `{"command": string, "timeout_s"?: number}`,
    needsApproval: true,
    subagentSafe: true,
    run: async (args) => {
      const command = str(args, "command");
      const timeout = Math.min(Number(args.timeout_s ?? 120), 600);
      return runBash(command, timeout);
    },
  });

  add({
    name: "remember",
    description:
      "Persist a fact to long-term memory (~/.glint/memory.md). Use for durable user preferences or project facts worth keeping across sessions.",
    args: `{"fact": string}`,
    needsApproval: false,
    subagentSafe: false,
    run: async (args) => {
      const fact = str(args, "fact");
      appendMemory(fact);
      return `remembered: ${fact}`;
    },
  });

  if (opts.onSubagent) {
    add({
      name: "subagent",
      description:
        "Delegate a self-contained research or analysis task to a fast subagent (groq/compound-mini). It has read-only file access, search, and shell. Returns its findings. Use for parallel exploration or to keep your own context small.",
      args: `{"task": string}`,
      needsApproval: false,
      subagentSafe: false,
      run: async (args) => {
        const task = str(args, "task");
        trace("subagent.start", { task: task.slice(0, 200) });
        const result = await opts.onSubagent!(task);
        trace("subagent.done", { chars: result.length });
        return cap(result);
      },
    });
  }

  return tools;
}

export async function executeTool(
  tools: Map<string, ToolSpec>,
  name: string,
  args: Record<string, unknown>,
): Promise<{ status: "ok" | "error"; output: string }> {
  const started = Date.now();
  const tool = tools.get(name);
  if (!tool) {
    const known = [...tools.keys()].join(", ");
    return { status: "error", output: `unknown tool "${name}". Available: ${known}` };
  }
  try {
    const output = await tool.run(args);
    logger.info("tool.run", { tool: name, ms: Date.now() - started });
    trace("tool.run", { tool: name, args: summarizeArgs(args), ms: Date.now() - started, ok: true });
    return { status: "ok", output };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    logger.warn("tool.error", { tool: name, error: message });
    trace("tool.run", { tool: name, args: summarizeArgs(args), ms: Date.now() - started, ok: false, error: message });
    return { status: "error", output: message };
  }
}

function summarizeArgs(args: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(args)) {
    out[k] = typeof v === "string" && v.length > 200 ? v.slice(0, 200) + "…" : v;
  }
  return out;
}
